const KEY='lele-pink-ledger-v2',OLD_KEY='lele-pink-ledger-v1';
let db,storageBlocked=false,recovery='',demo=false,realDb=null;
try{const raw=localStorage.getItem(KEY)||localStorage.getItem(OLD_KEY);db=raw?validateState(JSON.parse(raw)):freshState();}catch(e){db=freshState();storageBlocked=true;try{recovery=localStorage.getItem(KEY)||localStorage.getItem(OLD_KEY)||'';}catch{} }
let paymentFilter='all';
let page='dashboard',month=today().slice(0,7),scope='month',search='',typeFilter='all',categoryFilter='all',activityLimit=100,lastFocus=null;
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=c=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(c/100);
const shortMoney=c=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',notation:Math.abs(c)>=100000?'compact':'standard',maximumFractionDigits:0}).format(c/100);
const monthLabel=m=>new Date(Number(m.slice(0,4)),Number(m.slice(5))-1,1).toLocaleDateString('en-US',{month:'long',year:'numeric'});
const monthShort=m=>new Date(Number(m.slice(0,4)),Number(m.slice(5))-1,1).toLocaleDateString('en-US',{month:'short',year:'2-digit'});
const percent=(a,b)=>b>0?Math.round(a/b*100):0,clamp=n=>Math.max(0,Math.min(100,n));
const selectedWindow=()=>windowFor(db,scope,month);
const selectedRows=()=>entries(db,...selectedWindow());
const periodLabel=()=>scope==='month'?monthLabel(month):scope==='year'?month.slice(0,4):`All time · through ${monthLabel(today().slice(0,7))}`;
const dateDefault=()=>month===today().slice(0,7)?today():month+'-01';
const button=(action,label,id='',cls='')=>`<button class="button ${cls}" data-action="${action}" ${id?`data-id="${esc(id)}"`:''}>${label}</button>`;
const link=(p,label)=>`<button class="text-button" data-page="${p}">${label} →</button>`;
const empty=(icon,title,detail)=>`<div class="empty"><span>${icon}</span><b>${title}</b>${detail}</div>`;
const heading=(title,right='',note='')=>`<div class="section-head"><div><h2>${title}</h2>${note?`<p>${note}</p>`:''}</div>${right}</div>`;
const metric=(label,amount,sub='',plain=false)=>`<div class="metric"><div class="label">${label}</div><strong class="number">${plain?amount:money(amount)}</strong><div class="sub">${sub}</div></div>`;
const progressHTML=(n,max)=>`<div class="progress ${n>max&&max>0?'over':''}"><i style="width:${max?clamp(n/max*100):0}%"></i></div>`;
function notify(text){const el=$('#toast');el.textContent=text;el.hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>el.hidden=true,3300);}
function commit(change){const next=structuredClone(db);change(next);const validated=validateState(next);if(!demo){if(storageBlocked)throw Error('Storage could not be read. Restore a backup in Settings before saving.');try{localStorage.setItem(KEY,JSON.stringify(validated));}catch{throw Error('Your browser could not save this change. Download a backup in Settings and check storage permissions.');}}db=validated;}
const navItems=[['dashboard','⌂','Dashboard','Home'],['income','↙','Income','Income'],['expenses','↗','Expenses','Expenses'],['budgets','▥','Budgets & bills','Budgets'],['cards','▰','Cards & cash','Wallet'],['goals','♡','Goals & savings','Goals'],['activity','≡','All activity','Activity']];
const titles={cards:['Your pretty little wallet.','Every card, every cash purchase, all in one place.'],dashboard:['Your money, in full bloom.','Income, spending, savings — the whole picture.'],income:['The money coming in.','Your monthly income, every paycheck, and the unexpected #wins.'],expenses:['Where the money goes.','The everyday things, the little treats, and the big purchases.'],budgets:['A place for every dollar.','Your recurring bills and monthly category limits.'],goals:['Dream it. Fund it.','Trips, plans, and savings with a space of their own.'],activity:['Every little money move.','One complete history. Filter it however you like.'],settings:['Make yourself at home.','Your data, your categories, your pink little world.']};
function render(){
  $('#pageTitle').textContent=titles[page][0];$('#pageSubtitle').textContent=titles[page][1];
  $('#sideNav').innerHTML=navItems.map(([key,icon,label])=>`<button data-page="${key}" class="${page===key?'active':''}"><span class="nav-icon">${icon}</span>${label}</button>`).join('');
  $('#mobileNav').innerHTML=[...navItems,['settings','⚙','Settings','Settings']].map(([key,icon,,label])=>`<button data-page="${key}" class="${page===key?'active':''}" ${page===key?'aria-current="page"':''}><span>${icon}</span>${label}</button>`).join('');
  const ranges=['dashboard','income','expenses','activity','cards'].includes(page),dates=ranges||page==='budgets';
  $('#toolbar').innerHTML=(ranges?`<div class="segmented" aria-label="Date range">${[['month','Month'],['year','Year'],['all','All time']].map(([s,l])=>`<button data-scope="${s}" class="${scope===s?'active':''}" aria-pressed="${scope===s}">${l}</button>`).join('')}</div>`:'')+(dates&&(scope!=='all'||page==='budgets')?`<div class="date-control"><button data-action="previous-month" aria-label="Previous month">‹</button><input type="month" id="monthInput" aria-label="Selected month" min="1900-01" max="2099-12" value="${month}"><button data-action="next-month" aria-label="Next month">›</button></div>`:'')+(ranges?`<span class="toolbar-note">${esc(periodLabel())}${scope==='year'?' · includes scheduled months':''}</span>`:page==='goals'?'<span class="toolbar-note">Goal balances include all recorded contributions and purchases.</span>':'');
  $('#view').innerHTML=({cards:cardsView,dashboard:dashboardView,income:incomeView,expenses:expensesView,budgets:budgetsView,goals:goalsView,activity:activityView,settings:settingsView})[page]();
  $('#demoBanner').hidden=!demo;
  $('#storageBanner').hidden=!storageBlocked;
  if(storageBlocked)$('#storageBanner').textContent='Saved data could not be read. Editing is paused; use Settings to recover or restore a backup.';
}
function transactionList(rows,limit=100){return rows.length?rows.slice(0,limit).map(t=>{
  const icon=t.type==='card_payment'?'💳':t.type==='income'?'💸':t.type==='saving'?'🎀':t.type==='withdrawal'?'↩':ICONS[t.category]||'✨';
  const meta=[t.date,t.type==='income'?(t.automatic?'Recurring income':t.incomeKind||'Income'):t.type==='expense'?t.category:t.type==='saving'?'Contribution':t.type==='card_payment'?'Card payment · not an expense':'Returned from goal'];
  if(t.goalId)meta.push(db.goals.find(g=>g.id===t.goalId)?.name||'Goal');if(t.payment)meta.push(paymentLabel(t.payment));if(t.merchant)meta.push(t.merchant);
  return `<div class="list-row"><span class="list-icon">${icon}</span><div class="list-detail"><div class="list-title">${esc(t.name)} ${t.automatic?'<span class="tag auto">AUTO</span>':''}</div><div class="list-meta">${meta.map(esc).join(' · ')}${t.note?`<br>${esc(t.note)}`:''}</div></div><div class="list-amount ${t.type==='income'?'income-color':'expense-color'}">${['income','withdrawal'].includes(t.type)?'+':'−'}${money(t.cents)}</div><button class="icon-button" data-action="edit-entry" data-id="${esc(t.id)}" aria-label="Edit ${esc(t.name)}">✎</button></div>`;
}).join(''):empty('🧾','A fresh page.','Entries for this period will appear here.');}
const CHART_COLORS=['#e71379','#ff72b5','#aa2469','#f9a1ca','#c461a0','#ffbad9','#88345f','#e55da1'];
function spendingDonut(rows){let data=categoryTotals(rows);const total=data.reduce((s,x)=>s+x[1],0);if(!total)return empty('🍓','Your spending breakdown','Add an expense or fixed bill to see categories, amounts, and percentages.');if(data.length>6)data=[...data.slice(0,5),['Other categories',data.slice(5).reduce((s,x)=>s+x[1],0)]];let acc=0;const gradient=data.map(([,v],i)=>{const a=acc;acc+=v/total*100;return `${CHART_COLORS[i]} ${a}% ${acc}%`;}).join(',');return `<div class="chart-grid"><div class="donut" style="background:conic-gradient(${gradient})" role="img" aria-label="Spending ${money(total)}. Breakdown in adjacent legend."><div class="donut-hole"><strong>${shortMoney(total)}</strong><small>total spending</small></div></div><div class="legend">${data.map(([cat,v],i)=>`<div class="legend-row"><i class="dot" style="background:${CHART_COLORS[i]}"></i><span>${esc(cat)}<br><small>${percent(v,total)}% of spending</small></span><b>${money(v)}</b></div>`).join('')}</div></div>`;}
function trendChart(){const [start,end]=selectedWindow();const ms=scope==='month'?monthsBetween(shiftMonth(month,-5),month):monthsBetween(start,end).slice(-12),data=ms.map(m=>summarize(entries(db,m,m))),max=Math.max(100,...data.flatMap(t=>[t.income,t.expenses]));const width=560,height=211,left=48,right=8,top=15,bottom=33,areaH=height-top-bottom,col=(width-left-right)/ms.length;
  let shapes=[0,.5,1].map(p=>{const y=top+areaH*(1-p);return `<line class="gridline" x1="${left}" x2="${width-right}" y1="${y}" y2="${y}"/><text x="${left-7}" y="${y+3}" text-anchor="end">${shortMoney(max*p)}</text>`;}).join('');
  data.forEach((t,i)=>{const x=left+i*col+col*.2,bw=col*.24;for(const [v,offset,fill,name] of [[t.income,0,'#f57ab2','Income'],[t.expenses,bw+2,'#c0146a','Spending']]){const h=v/max*areaH;shapes+=`<rect x="${x+offset}" y="${top+areaH-h}" width="${bw}" height="${h}" rx="3" fill="${fill}"><title>${esc(monthLabel(ms[i]))} ${name}: ${money(v)}</title></rect>`;}shapes+=`<text x="${left+i*col+col/2}" y="${height-10}" text-anchor="middle" style="font-size:${ms.length>8?8:10}px">${monthShort(ms[i])}</text>`;});
  return `<svg class="chart-svg" viewBox="0 0 ${width} ${height}" role="img" aria-label="Income and spending by month. Exact amounts are in the monthly history table.">${shapes}</svg><div class="chart-key"><span><i style="background:#f57ab2"></i>Income</span><span><i style="background:#c0146a"></i>Spending</span></div><p class="help">${scope==='month'?'Six months ending':ms.length===12?'Latest 12 months through':'Months through'} ${esc(monthLabel(ms.at(-1)))}</p>`;
}
function dailyChart(rows){const spent=rows.filter(t=>t.type==='expense'),days=lastDay(month),values=Array(days).fill(0);spent.forEach(t=>values[Number(t.date.slice(8))-1]+=t.cents);let total=0;const cumulative=values.map(v=>total+=v),max=Math.max(100,total),points=cumulative.map((v,i)=>`${42+i*490/(days-1)},${153-v/max*130}`),path=points.map((p,i)=>(i?'L':'M')+p).join(' ');return `<svg class="chart-svg" viewBox="0 0 550 190" role="img" aria-label="Cumulative spending in ${monthLabel(month)}, ending at ${money(total)}"><defs><linearGradient id="pinkArea" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#ec398b" stop-opacity=".3"/><stop offset="1" stop-color="#ec398b" stop-opacity=".03"/></linearGradient></defs>${[0,.5,1].map(p=>`<line class="gridline" x1="42" x2="532" y1="${153-p*130}" y2="${153-p*130}"/><text x="35" y="${156-p*130}" text-anchor="end">${shortMoney(max*p)}</text>`).join('')}<path d="${path} L532,153 L42,153 Z" fill="url(#pinkArea)"/><path d="${path}" fill="none" stroke="#e21577" stroke-width="3" stroke-linejoin="round"/><text x="42" y="178">Day 1</text><text x="287" y="178" text-anchor="middle">Day ${Math.round(days/2)}</text><text x="532" y="178" text-anchor="end">Day ${days}</text></svg><p class="help">Cumulative expenses, including fixed bills on their configured days.</p>`;}
function budgetOverview(rows,start,end,limit=5){const cats=[...new Set([...db.categories,...db.budgets.map(b=>b.category)])],spent=new Map(categoryTotals(rows)),configured=cats.map(c=>({cat:c,cap:budgetAcross(db,c,start,end),spent:spent.get(c)||0})).filter(x=>x.cap>0).sort((a,b)=>b.spent/b.cap-a.spent/a.cap);if(!configured.length)return empty('🎟️','Give your categories a budget',`Set monthly limits in Budgets & bills. ${link('budgets','Set budgets')}`);return configured.slice(0,limit).map(x=>`<div class="budget-row"><div class="row"><b>${ICONS[x.cat]||'✨'} ${esc(x.cat)}</b><span class="tag ${x.spent>x.cap?'warn':''}">${x.spent>x.cap?money(x.spent-x.cap)+' over':money(x.cap-x.spent)+' left'}</span></div>${progressHTML(x.spent,x.cap)}<div class="row row-space"><span class="muted">${money(x.spent)} spent</span><span class="muted">${money(x.cap)} budget</span></div></div>`).join('');}
function historyTable(){const [a,b]=selectedWindow(),months=scope==='month'?monthsBetween(shiftMonth(month,-5),month):monthsBetween(a,b),rows=months.map(m=>[m,summarize(entries(db,m,m))]);return `<div class="table-wrap"><table class="table"><thead><tr><th>Month</th><th>Income</th><th>Fixed bills</th><th>Other spending</th><th>Net to goals</th><th>Left</th></tr></thead><tbody>${rows.slice().reverse().map(([m,t])=>`<tr><td>${esc(monthShort(m))}</td><td>${money(t.income)}</td><td>${money(t.fixed)}</td><td>${money(t.variable)}</td><td>${money(t.netSaved)}</td><td><b>${money(t.left)}</b></td></tr>`).join('')}</tbody></table></div>`;}
function dashboardView(){const rows=selectedRows(),t=summarize(rows),[a,b]=selectedWindow(),cats=categoryTotals(rows),expenses=rows.filter(r=>r.type==='expense'),largest=[...expenses].sort((a,b)=>b.cents-a.cents)[0],prev=summarize(entries(db,shiftMonth(month,-1),shiftMonth(month,-1))),delta=t.expenses-prev.expenses;
  const stats=`<div class="metrics">${metric('↙ Total income',t.income,`${money(t.regularIncome)} recurring · ${money(t.extraIncome)} extra`)}${metric('↗ Total spending',t.expenses,`${money(t.fixed)} fixed · ${money(t.variable)} other`)}${metric('♡ Net set aside',t.netSaved,`${money(t.contributions)} added · ${money(t.withdrawals+t.goalSpent)} used/returned`)}${metric('✧ Savings rate',t.income?percent(t.netSaved,t.income)+'%':'—',t.income?'Net set aside ÷ total income':'Add income to calculate',true)}</div>`;
  return `${!db.rules.some(r=>r.type==='income')?`<div class="strip"><div><b>Let’s put your monthly income to work.</b><p>Set it once. It is included automatically every month from your chosen start date.</p></div>${button('new-income-rule','Set monthly income','','primary')}</div>`:''}<div class="grid hero-grid"><div class="card hero"><small>${scope==='month'?'LEFT THIS MONTH':'LEFT IN THIS PERIOD'}</small><div class="hero-number">${money(t.left)}</div><p>Income minus spending and net money set aside.<br>Recurring income and bills are included automatically.</p><div class="hero-pills"><span>${t.count} money movements</span><span>${t.expenseCount} expenses</span></div></div>${stats}</div><div class="section-head"><h2>Your money moves</h2></div><div class="actions">${button('new-expense','＋ Add expense','','primary')}${button('new-income','＋ Add extra income','','soft')}${link('goals','Go to savings goals')}</div><div class="grid two-col"><section>${heading('Where it went',link('expenses','Expenses'))}<div class="card">${spendingDonut(rows)}</div></section><section>${heading('The income & spending story')}<div class="card">${trendChart()}</div></section></div><div class="grid three-col" style="margin-top:17px">${metric('Biggest spending category',cats[0]?esc(cats[0][0]):'—',cats[0]?money(cats[0][1])+' · '+percent(cats[0][1],t.expenses)+'% of spending':'No spending in this period',true)}${metric('Largest expense',largest?largest.cents:0,largest?esc(largest.name):'No expenses yet')}${metric(scope==='month'?'Spending vs last month':'Average expense',scope==='month'?(prev.expenses?`${delta>=0?'+':'−'}${money(Math.abs(delta))}`:'—'):(t.expenseCount?money(Math.round(t.expenses/t.expenseCount)):'—'),scope==='month'?(prev.expenses?`${Math.abs(percent(delta,prev.expenses))}% ${delta>=0?'more':'less'} than ${monthShort(shiftMonth(month,-1))}`:'No previous-month spending to compare'):`Across ${t.expenseCount} expenses`,true)}</div><div class="grid two-col"><section>${heading(scope==='month'?'Spending through the month':'Category budget check',scope==='month'?'':link('budgets','Budgets'))}<div class="card">${scope==='month'?dailyChart(rows):budgetOverview(rows,a,b)}</div></section><section>${heading(scope==='month'?'Your category limits':'Recent activity',scope==='month'?link('budgets','All budgets'):link('activity','All activity'))}<div class="card">${scope==='month'?budgetOverview(rows,a,b):transactionList(rows,5)}</div></section></div>${heading('Monthly history','',scope==='month'?'Your last six months, with exact amounts.':'Every month in the selected period.')}<div class="card">${historyTable()}<p class="help">“Net to goals” = contributions − money returned − purchases paid from goals. Goal-funded purchases count as spending and use saved funds, so they do not reduce available money twice.</p></div>${!rows.length?`<div class="strip" style="margin-top:20px"><div><b>Want to see the dashboard filled in?</b><p>Sample mode has a separate ledger you can explore.</p></div>${button('enter-demo','Explore sample data')}</div>`:''}`;
}
function currentRules(type){return db.rules.filter(r=>r.type===type&&r.start<=month&&(!r.end||r.end>=month));}
function ruleCards(type){const rules=currentRules(type);return rules.length?rules.map(r=>`<div class="list-row"><span class="list-icon">${type==='income'?'💸':ICONS[r.category]||'📅'}</span><div class="list-detail"><div class="list-title">${esc(r.name)} <span class="tag auto">AUTO MONTHLY</span></div><div class="list-meta">${money(r.cents)} on day ${r.day} · From ${esc(monthShort(r.start))}${r.end?' through '+esc(monthShort(r.end)):''}${type==='expense'?' · '+esc(r.category):''}</div></div>${button('edit-rule','Edit',r.id,'small')}</div>`).join(''):empty(type==='income'?'💸':'📅',type==='income'?'Add your regular income':'No fixed bills for this month',type==='income'?'It will show up automatically in each month.':'Rent, tithing, subscriptions — set each up once.');}
function incomeView(){const rows=selectedRows().filter(t=>t.type==='income'),t=summarize(rows);return `<div class="actions">${button('new-income-rule','＋ Monthly income','','primary')}${button('new-income','＋ Extra income / #win','','soft')}</div><div class="compact-stats" style="margin-top:18px;grid-template-columns:repeat(3,minmax(0,1fr))">${metric('Total income',t.income)}${metric('Recurring income',t.regularIncome,'Applied automatically')}${metric('Extra income',t.extraIncome,'Bonuses, gifts & other wins')}</div>${heading('Your monthly income sources','',`Sources active in ${monthLabel(month)}`)}<div class="card">${ruleCards('income')}</div><p class="help">Your recurring amount is already counted. If one month is different, edit its AUTO entry below. Use “Extra income” for money in addition to your recurring amount.</p>${heading('Income history',button('new-income','＋ Extra income'))}<div class="card">${transactionList(rows)}</div>${rows.length>100?'<p class="help">Latest 100 shown. Use All activity to search or load more.</p>':''}`;}
function expensesView(){const rows=selectedRows().filter(t=>t.type==='expense'),t=summarize(rows);return `<div class="actions">${button('new-expense','＋ Add expense','','primary')}${button('new-bill','＋ Fixed bill','','soft')}</div><div class="compact-stats" style="margin-top:18px;grid-template-columns:repeat(3,minmax(0,1fr))">${metric('Total expenses',t.expenses)}${metric('Fixed bills',t.fixed,'Automatic monthly expenses')}${metric('Other spending',t.variable,'One-off purchases')}</div><div class="grid equal-col"><section>${heading('By category')}<div class="card">${spendingDonut(rows)}</div></section><section>${heading('Spending detail')}<div class="card"><div class="row"><span class="label">Paid from savings goals</span><b>${money(t.goalSpent)}</b></div><div class="divider"></div><div class="row"><span class="label">Average expense</span><b>${money(t.expenseCount?Math.round(t.expenses/t.expenseCount):0)}</b></div><div class="divider"></div><div class="row"><span class="label">Expense count</span><b>${t.expenseCount}</b></div><p class="help">Goal purchases appear here and reduce the goal’s balance. Fixed bills are included once per month.</p></div></section></div>${heading('Expense history',link('activity','Search all activity'))}<div class="card">${transactionList(rows)}</div>${rows.length>100?'<p class="help">Latest 100 shown. Use All activity to search or load more.</p>':''}`;}
function budgetsView(){const rows=entries(db,month,month),spent=new Map(categoryTotals(rows)),totalBudget=db.categories.reduce((s,c)=>s+budgetAt(db,c,month),0),fixed=sumC(rows.filter(r=>r.type==='expense'&&r.automatic));return `<div class="compact-stats" style="grid-template-columns:1fr 1fr">${metric('Category limits',totalBudget,'Monthly spending targets')}${metric('Fixed bills included',fixed,'Counted automatically in spending')}</div>${heading('Fixed bills',button('new-bill','＋ Fixed bill','','primary'))}<div class="card">${ruleCards('expense')}</div><p class="help">A fixed bill is applied every month from its start date. Edit an individual AUTO entry in Activity if that month’s charge differs. End a recurring bill to stop future charges.</p>${heading('Monthly category budgets',button('new-category','＋ Category'))}<div class="notice">Category limits are targets, not extra expenses. For example, a $600 rent bill uses $600 of your Housing budget. Budget changes apply from ${esc(monthLabel(month))} onward.</div><div class="grid three-col">${db.categories.map(c=>{const cap=budgetAt(db,c,month),v=spent.get(c)||0;return `<div class="card"><div class="row"><b style="font-size:13px">${ICONS[c]||'✨'} ${esc(c)}</b><button class="text-button" data-action="edit-budget" data-id="${esc(c)}">${cap?'Edit':'Set limit'}</button></div><div style="font-size:26px;font-weight:850;margin:18px 0 5px">${money(v)}</div><div class="muted">${cap?'of '+money(cap)+' monthly budget':'No limit set'}</div>${cap?progressHTML(v,cap):''}<div class="muted row-space">${cap?(v>cap?money(v-cap)+' over budget':money(cap-v)+' left'):'Spent this month'}</div></div>`;}).join('')}</div>`;}
function goalsView(){const stats=db.goals.map(g=>goalStats(db,g.id)),balance=stats.reduce((s,g)=>s+g.balance,0),spent=stats.reduce((s,g)=>s+g.spent,0),target=db.goals.reduce((s,g)=>s+g.target,0);return `<div class="strip"><div><b>Your dreams have their own home. 🎀</b><p>Contribute, spend from a goal, or move money back whenever plans change.</p></div>${button('new-goal','＋ New goal','','primary')}</div><div class="compact-stats" style="grid-template-columns:repeat(3,minmax(0,1fr))">${metric('Available in goals',balance)}${metric('Used toward your plans',spent)}${metric('Combined targets',target)}</div><div class="grid three-col">${db.goals.map(g=>{const s=goalStats(db,g.id),remaining=Math.max(0,g.target-s.balance),due=g.due?new Date(g.due+'T12:00:00'):null,n=due?Math.max(1,(due.getFullYear()-new Date().getFullYear())*12+due.getMonth()-new Date().getMonth()+1):0,expired=g.due&&g.due<today();return `<div class="card goal-card"><div class="row"><div class="goal-emoji">${esc(g.emoji)}</div><button class="text-button" data-action="edit-goal" data-id="${g.id}">Edit goal</button></div><h3>${esc(g.name)}</h3><div class="goal-balance">${money(s.balance)}</div><div class="muted">available${g.target?' · target '+money(g.target):' · no target set'}</div>${progressHTML(s.balance,g.target)}<div class="goal-detail">${g.target?`${percent(s.balance,g.target)}% currently funded · ${money(remaining)} to go`:'Set a target to see your progress.'}${g.due?`<br>Target date: ${esc(g.due)}${expired?' · date has passed':remaining&&g.target?' · ~'+money(Math.ceil(remaining/n))+'/month to reach it':''}`:''}<br>${money(s.added)} contributed · ${money(s.spent)} spent · ${money(s.withdrawn)} returned${g.opening?'<br>Opening balance: '+money(g.opening):''}</div><div class="actions">${button('contribute','＋ Add funds',g.id,'primary')}${button('goal-spend','Spend',g.id,'soft')}</div><button class="text-button" style="margin-top:8px" data-action="withdraw" data-id="${g.id}">Return money to available balance ↩</button><details><summary>Goal history (${s.rows.length})</summary>${transactionList(s.rows.slice().sort((a,b)=>b.date.localeCompare(a.date)),50)}</details></div>`;}).join('')||`<div class="card">${empty('🎀','Start with a little dream.','Create a goal for a trip, a purchase, or your savings.')}</div>`}</div>`;}
function filteredActivity(){let rows=selectedRows();if(typeFilter!=='all')rows=rows.filter(t=>t.type===typeFilter);if(paymentFilter!=='all')rows=rows.filter(t=>(paymentAccount(db,t.payment)?.id||'unassigned')===paymentFilter);if(categoryFilter!=='all')rows=rows.filter(t=>t.category===categoryFilter);const q=search.trim().toLowerCase();if(q)rows=rows.filter(t=>[t.name,t.note,t.category,paymentLabel(t.payment),t.merchant,t.incomeKind,db.goals.find(g=>g.id===t.goalId)?.name||''].some(v=>String(v||'').toLowerCase().includes(q)));return rows;}
function activityBody(){const rows=filteredActivity(),t=summarize(rows);return `<div class="count-note">${rows.length} matching entries · Income ${money(t.income)} · Expenses ${money(t.expenses)} · Net to goals ${money(t.netSaved)}</div><div class="card">${transactionList(rows,activityLimit)}</div>${rows.length>activityLimit?`<div style="text-align:center;margin-top:15px">${button('load-more','Show 100 more')}</div>`:''}`;}
function activityView(){return `<div class="filters">${paymentFilterHTML()}<input id="searchActivity" type="search" placeholder="Search names, notes, goals…" aria-label="Search activity" value="${esc(search)}"><select id="typeFilter" aria-label="Type filter">${[['all','All movements'],['income','Income'],['expense','Expenses'],['saving','Goal contributions'],['withdrawal','Goal withdrawals'],['card_payment','Card payments']].map(([v,l])=>`<option value="${v}" ${typeFilter===v?'selected':''}>${l}</option>`).join('')}</select><select id="categoryFilter" aria-label="Category filter"><option value="all">All categories</option>${db.categories.map(c=>`<option ${categoryFilter===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="row" style="margin-bottom:15px"><p class="muted">AUTO entries are recurring income and bills. Edit one to adjust that month only.</p>${button('export-csv','↓ CSV','','small')}</div><div id="activityBody">${activityBody()}</div>`;}
function settingsView(){return `${heading('Keep your money diary safe')}<div class="card"><h3>Backup & restore</h3><p class="help">Your ledger stays in this browser. Download a backup before clearing browser data or switching files/devices. Older Pink Ledger backups can be imported too.</p><div class="actions">${button('export','↓ Download backup','','primary')}${button('import','↑ Restore backup')}${recovery?button('recovery','Download recovery data'):''}</div><input id="importFile" type="file" accept=".json,application/json" hidden><p class="help">Restore replaces this ledger after you confirm. Export first to keep your current copy.</p></div>${heading('Explore the full dashboard')}<div class="card"><h3>Try it with sample money</h3><p class="help">A separate sample ledger has six months of income, purchases, budgets, and goals. Your own data stays separate.</p>${button(demo?'exit-demo':'enter-demo',demo?'Return to my ledger':'Open sample ledger','','soft')}</div>${heading('How the numbers work')}<div class="card"><p class="help" style="margin-top:0">Recurring income and bills are automatically included once per calendar month, including when you view a future month. “All time” runs through the current month; “Year” includes all scheduled months in that year. These are your tracked and configured amounts, not a live bank balance.</p><p class="help">Available = income − expenses − goal contributions + goal withdrawals + purchases funded from goals. This keeps a goal-funded purchase from using your available money twice.</p><p class="help">Budget limits do not subtract money. Opening goal balances represent savings from before this ledger and do not reduce current income. Currency: USD.</p></div>`;}
function paymentLabel(value){return paymentAccount(db,value)?.name||value||'Not assigned';}
function paymentField(value){const known=paymentAccount(db,value);return selectField('Payment method','payment',[['','Not assigned'],...(db.accounts||defaultAccounts()).map(a=>[a.id,a.name]),...(!known&&value?[[value,value+' (previous label)']]:[])],known?.id||value);}
function paymentFilterHTML(){return `<select id="paymentFilter" aria-label="Payment method filter"><option value="all">All cards & cash</option>${(db.accounts||defaultAccounts()).map(a=>`<option value="${a.id}" ${paymentFilter===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}<option value="unassigned" ${paymentFilter==='unassigned'?'selected':''}>Not assigned / other</option></select>`;}
function cardsView(){
  const accounts=db.accounts||defaultAccounts(),rows=selectedRows(),spending=rows.filter(t=>t.type==='expense'),unassigned=spending.filter(t=>!paymentAccount(db,t.payment));
  const credit=accounts.filter(a=>a.kind==='credit'),limit=credit.reduce((s,a)=>s+a.limit,0),configured=credit.every(a=>a.opening!==null),balances=credit.map(a=>cardStats(db,a.id));
  return `${heading('Your cards & cash',button('new-card','＋ New card','','primary'))}<div class="notice">Spending follows your selected period and includes scheduled bills. Card balances are calculated through today (${today()}) from an opening balance, recorded charges, and card payments. These are tracked estimates, not live bank balances.</div><div class="compact-stats">${metric('Total credit limits',limit)}${metric('Card spending in period',sumC(spending.filter(t=>paymentAccount(db,t.payment)?.kind==='credit')))}${metric('Cash spending in period',sumC(spending.filter(t=>paymentAccount(db,t.payment)?.kind==='cash')))}${metric('Total tracked card balance',configured?money(balances.reduce((s,a)=>s+a.balance,0)):'Set opening balances',configured?'As of today':'Each card can start with $0 or an existing balance',true)}</div><div class="grid equal-col">${accounts.map(a=>{
    const purchases=spending.filter(t=>paymentAccount(db,t.payment)?.id===a.id),total=sumC(purchases),s=cardStats(db,a.id),isCard=a.kind==='credit',merchants=new Map();
    purchases.forEach(t=>{const key=t.merchant||'Merchant not recorded';merchants.set(key,(merchants.get(key)||0)+t.cents);});const top=[...merchants].sort((a,b)=>b[1]-a[1]).slice(0,5);
    return `<div class="card wallet-card wallet-${a.id}"><div class="row"><span class="tag">${isCard?'CREDIT CARD':'CASH'}</span>${isCard?button('edit-account','Balance & limit',a.id,'small'):''}</div><h3 style="margin:18px 0 8px;font-size:22px">${esc(a.name)}</h3><div class="muted">${isCard?'Credit limit '+money(a.limit):'Your cash purchases, tracked separately'}</div><div class="goal-balance">${money(total)}</div><div class="muted">spent in selected period · ${purchases.length} purchases</div>${isCard?`<div class="divider"></div>${s.balance===null?`<p class="help">Spending is ready to track. Set an opening balance to calculate what you owe and available credit.</p>`:`<div class="row"><span class="label">Tracked balance today</span><b>${money(s.balance)}</b></div><div class="row row-space"><span class="label">Available credit</span><b>${money(s.available)}</b></div>${progressHTML(Math.max(0,s.balance),a.limit)}<div class="muted row-space">${s.utilization===null?'No limit set':s.utilization.toFixed(1)+'% of limit used'}${s.balance>a.limit?' · Over limit':''}${s.balance<0?' · Credit balance':''}</div><div class="help">Opening balance ${money(a.opening)} on ${a.start}; charges and payments on/after that date are included.</div>`}<div class="actions">${button('card-payment','＋ Log card payment',a.id,'primary')}</div>`:''}<div class="actions" style="margin-top:12px">${button('account-history','View all transactions →',a.id)}</div><details><summary>Where you spent · top merchants</summary>${top.length?top.map(([m,v])=>`<div class="row row-space"><span class="muted">${esc(m)}</span><b style="font-size:12px">${money(v)}</b></div>`).join(''):empty('🛍️','No purchases yet','Choose this payment method when adding an expense.')}</details></div>`;
  }).join('')}</div>${unassigned.length?`${heading('Not assigned to a card or cash','',money(sumC(unassigned))+' in this period. Edit these expenses to assign a method.')}<div class="card">${transactionList(unassigned,30)}</div>`:''}`;
}
function accountModal(id=''){const old=db.accounts.find(a=>a.id===id),a=old||{name:'',limit:0,opening:null,start:today()};formModal(old?a.name+' · card details':'Add a new credit card',`<div class="form-grid">${field('Card name','name',a.name,'text','maxlength="60" required placeholder="e.g. My new card"')}${field('Credit limit (USD)','limit',old?a.limit/100:'','number','min="0" step="0.01" required')}${field('Opening balance owed (USD)','opening',a.opening===null?'':a.opening/100,'number','min="0" step="0.01" placeholder="Leave blank to track spending only"')}${field('Opening balance date','start',a.start,'date',`min="1900-01-01" max="${today()}" required`)}</div><p class="help">Enter the balance before any charges or payments on your opening date. Earlier expenses still appear in spending history but are not added again to this balance. Use $0 for a paid-off card. Leave the balance blank if you only want spending totals.</p>`,f=>commit(next=>{const name=String(f.get('name')).trim();if(!name)throw Error('Enter a card name.');if(next.accounts.some(x=>x.id!==id&&x.name.toLowerCase()===name.toLowerCase()))throw Error('A payment method with that name already exists.');const account=old?next.accounts.find(a=>a.id===id):{id:newId(),kind:'credit'};account.name=name;account.limit=numeric(f,'limit',true);account.opening=String(f.get('opening')).trim()===''?null:numeric(f,'opening',true);account.start=String(f.get('start'));if(!old)next.accounts.push(account);}),'Save card');}
function cardPaymentModal(accountId,id=''){const old=db.transactions.find(t=>t.id===id),accounts=db.accounts.filter(a=>a.kind==='credit');formModal(old?'Edit card payment':'Log a card payment',`<div class="form-grid">${selectField('Card paid','payment',accounts.map(a=>[a.id,a.name]),paymentAccount(db,old?.payment||accountId)?.id||accounts[0]?.id)}${field('Payment amount (USD)','amount',old?old.cents/100:'','number','min="0.01" step="0.01" required')}${field('Payment date','date',old?.date||today(),'date',`min="1900-01-01" max="${today()}" required`)}${noteField(old?.note)}</div><p class="help">This reduces the tracked card balance. It is not another expense: purchases were already counted when logged. An opening balance is needed for balance and available-credit calculations.</p>`,f=>commit(next=>{const payment=String(f.get('payment'));const t={id:old?.id||newId(),type:'card_payment',cents:numeric(f),date:String(f.get('date')),payment,name:'Payment to '+paymentLabel(payment),category:'Card payment',goalId:'',note:String(f.get('note')||''),merchant:'',incomeKind:''};if(old)next.transactions=next.transactions.map(x=>x.id===id?t:x);else next.transactions.push(t);}),'Save card payment',old?button('delete-entry','Delete',id,'danger'):'');}
function field(label,name,value='',type='text',attrs=''){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${attrs}></div>`;}
function selectField(label,name,opts,value){return `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${opts.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('')}</select></div>`;}
const noteField=value=>`<div class="field full"><label for="f-note">Note (optional)</label><textarea id="f-note" name="note" maxlength="500">${esc(value||'')}</textarea></div>`;
function formModal(title,body,submit,saveLabel='Save',footer=''){
  lastFocus=document.activeElement;$('#dialogTitle').textContent=title;$('#dialogContent').innerHTML=`<form id="editForm">${body}<div class="form-error" role="alert" id="formError"></div><div class="form-actions">${footer}<button type="button" class="button" data-action="close-dialog">Cancel</button><button type="submit" class="button primary">${saveLabel}</button></div></form>`;
  const dialog=$('#dialog');if(!dialog.open)dialog.showModal();$('#editForm').onsubmit=e=>{e.preventDefault();try{submit(new FormData(e.target));closeDialog();render();notify(demo?'Sample ledger updated ♡':'Saved to your ledger ♡');}catch(err){$('#formError').textContent=err.message;}};
}
function closeDialog(){$('#dialog').close();lastFocus?.focus?.();}
function numeric(f,name='amount',allowZero=false){const raw=f.get(name);if(raw===null||String(raw).trim()==='')throw Error('Enter an amount.');const n=cents(raw);if(!Number.isSafeInteger(n)||n<(allowZero?0:1)||n>10000000000)throw Error('Enter a valid '+(allowZero?'zero or positive':'positive')+' amount.');return n;}
function entryModal(type,id='',goalId=''){
  const old=db.transactions.find(t=>t.id===id);if(old?.type==='card_payment')return cardPaymentModal(old.payment,id);if(old){type=old.type;goalId=old.goalId;}
  const g=db.goals.find(g=>g.id===goalId),isGoal=['saving','withdrawal'].includes(type),expense=type==='expense',income=type==='income';
  const title=old?`Edit ${income?'income':expense?'expense':type==='saving'?'contribution':'withdrawal'}`:income?'Add extra income / #win':expense?(g?'Spend from '+g.name:'Add an expense'):type==='saving'?'Add funds to '+g?.name:'Return money from '+g?.name;
  let body=`<div class="form-grid">${field('Amount (USD)','amount',old?old.cents/100:'','number','min="0.01" max="100000000" step="0.01" required')}${field('Date','date',old?.date||dateDefault(),'date','min="1900-01-01" max="2099-12-31" required')}${!isGoal?field(income?'Source / description':'What was it?','name',old?.name||'','text','maxlength="100" required'):''}${income?selectField('Income kind','incomeKind',[['Bonus','Bonus'],['Gift','Gift'],['Refund','Refund / reimbursement'],['Side income','Side income'],['Other','Other']],old?.incomeKind||'Bonus'):''}${expense?selectField('Category','category',db.categories.map(c=>[c,c]),old?.category||(g?'Travel':'Other')):''}${expense?selectField('Paid from','goalId',[['','Available monthly money'],...db.goals.map(g=>[g.id,g.name+' · '+money(goalStats(db,g.id).balance)])],goalId):''}${expense?paymentField(old?.payment||''):''}${expense?field('Where spent / merchant (optional)','merchant',old?.merchant||'','text','maxlength="100" placeholder="e.g. Target, Regal, Rhode"'):''}${noteField(old?.note)}</div>`;
  body+=`<p class="help">${income?'This is added on top of your recurring monthly income. Change an AUTO entry if you are correcting that month’s regular income.':expense?'A goal-funded purchase reduces that goal and appears in spending. Its saved funds cover the purchase.':type==='saving'?'This moves money out of available funds and into your goal.':'This moves money out of the goal and back into available funds. It is not new income.'}</p>`;
  formModal(title,body,f=>commit(next=>{const entry={id:old?.id||newId(),type,cents:numeric(f),date:String(f.get('date')),name:isGoal?(type==='saving'?'Contribution to ':'Return from ')+(g?.name||'goal'):String(f.get('name')).trim(),category:expense?String(f.get('category')):income?'Income':'Savings',goalId:expense?String(f.get('goalId')||''):isGoal?goalId:'',note:String(f.get('note')||''),payment:String(f.get('payment')||''),merchant:String(f.get('merchant')||''),incomeKind:income?String(f.get('incomeKind')||'Other'):''};if(old)next.transactions=next.transactions.map(t=>t.id===id?entry:t);else next.transactions.push(entry);}),old?'Save changes':income?'Add extra income':expense?'Save expense':type==='saving'?'Add to goal':'Return money',old?button('delete-entry','Delete',id,'danger'):'' );
}
function ruleModal(type,id=''){
  const old=db.rules.find(r=>r.id===id);if(old)type=old.type;
  const effective=old&&month<old.start?old.start:month;
  const body=`<div class="form-grid">${field(type==='income'?'Income source':'Bill name','name',old?.name||(type==='income'?'Monthly income':''),'text','maxlength="100" required')}${field('Monthly amount (USD)','amount',old?old.cents/100:'','number','min="0.01" max="100000000" step="0.01" required')}${field(old?'Change from month':'Start month','start',effective,'month','min="1900-01" max="2099-12" required')}${field('Day of month','day',old?.day||1,'number','min="1" max="31" step="1" required')}${type==='expense'?selectField('Category','category',db.categories.map(c=>[c,c]),old?.category||'Subscriptions'):''}${type==='expense'?paymentField(old?.payment||''):''}</div><p class="help">${type==='income'?'This amount is automatically included as income every month.':'This charge is automatically included as an expense every month.'} ${old?'Changes take effect from your chosen month. Earlier months keep their amounts.':'Choose the first month you want it to apply.'} Days 29–31 fall on the last day of shorter months.</p>`;
  formModal(old?'Edit recurring '+(type==='income'?'income':'bill'):type==='income'?'Set monthly income':'Add a fixed bill',body,f=>commit(next=>{const r={name:String(f.get('name')).trim(),cents:numeric(f),type,category:type==='income'?'Income':String(f.get('category')),day:Number(f.get('day')),payment:type==='expense'?String(f.get('payment')||''):''},start=String(f.get('start'));if(old)reviseRule(next,id,r,start);else next.rules.push({...r,id:newId(),start,end:''});}),old?'Save recurring change':'Apply every month',old?button('end-rule','End recurring item',id,'danger'):'' );
}
function overrideModal(id){const parts=id.split(':'),m=parts[2],t=entries(db,m,m).find(t=>t.id===id);if(!t)return;formModal('Adjust this month only',`<div class="notice">${esc(t.name)} · ${esc(monthLabel(m))}. Other months keep their recurring amounts.</div><div class="form-grid">${field('Amount (USD)','amount',t.cents/100,'number','min="0.01" max="100000000" step="0.01" required')}${field('Date in this month','date',t.date,'date',`min="${m}-01" max="${m}-${lastDay(m)}" required`)}${field('Description','name',t.name,'text','maxlength="100" required')}${noteField(t.note)}</div>`,f=>commit(next=>{next.overrides[id]={cents:numeric(f),date:String(f.get('date')),name:String(f.get('name')).trim(),note:String(f.get('note')||'')};}),'Save this month',button('skip-auto','Skip this month',id,'danger')+(db.overrides[id]?button('reset-auto','Use recurring amount',id):''));}
function goalModal(id=''){const old=db.goals.find(g=>g.id===id);formModal(old?'Edit your goal':'A new little dream',`<div class="form-grid">${field('Goal name','name',old?.name||'','text','maxlength="100" required')}${field('Emoji','emoji',old?.emoji||'🎀','text','maxlength="16" required')}${field('Target (USD; 0 = no target)','target',old?old.target/100:0,'number','min="0" step="0.01" required')}${field('Already saved before this ledger','opening',old?old.opening/100:0,'number','min="0" step="0.01" required')}${field('Target date (optional)','due',old?.due||'','date','min="1900-01-01" max="2099-12-31"')}</div><p class="help">Use “Already saved” for an opening balance. New contributions belong in “Add funds” so they are reflected in that month’s money.</p>`,f=>commit(next=>{const goal={id:old?.id||newId(),name:String(f.get('name')).trim(),emoji:String(f.get('emoji')).trim(),target:numeric(f,'target',true),opening:numeric(f,'opening',true),due:String(f.get('due')||'')};if(old)next.goals=next.goals.map(g=>g.id===id?goal:g);else next.goals.push(goal);}),'Save goal',old?button('delete-goal','Delete goal',id,'danger'):'' );}
function budgetModal(cat){formModal('Budget for '+cat,`${field('Monthly limit (USD)','amount',budgetAt(db,cat,month)/100,'number','min="0" max="100000000" step="0.01" required')}<p class="help">Applies from ${esc(monthLabel(month))} onward. Earlier months keep their budgets. Set 0 to remove the limit from this month.</p>`,f=>commit(next=>setBudget(next,cat,numeric(f,'amount',true),month)),'Save monthly limit');}
function endRuleModal(id){const r=db.rules.find(r=>r.id===id);formModal('End recurring '+r.name,`${field('First month without this item','stop',month<r.start?r.start:month,'month','min="1900-01" max="2099-12" required')}<p class="help">Earlier months remain in your history. This also stops any future amount changes for this recurring item.</p>`,f=>commit(next=>endRecurring(next,id,String(f.get('stop')))), 'End recurring item');}
function download(name,content,type){if(globalThis.AndroidLedger?.saveText){globalThis.AndroidLedger.saveText(name,content,type.split(';')[0]);return;}const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function sampleState(){const first=shiftMonth(today().slice(0,7),-5),s=freshState(),goal=s.goals[0],disney=s.goals[1];goal.target=200000;disney.target=350000;s.goals[2].target=500000;s.goals[2].opening=85000;
  s.rules=[{id:newId(),name:'Monthly pay',type:'income',cents:500000,category:'Income',day:1,start:first,end:''},...[[60000,'Rent','Housing',1],[20000,'Tithing','Tithing',5],[2499,'Movie subscription','Subscriptions',10]].map(([cents,name,category,day])=>({id:newId(),name,type:'expense',cents,category,day,start:first,end:''}))];
  for(const [category,amount] of [['Housing',65000],['Tithing',20000],['Shopping',30000],['Dining',18000],['Entertainment',15000],['Beauty',10000],['Transport',10000],['Subscriptions',5000]])s.budgets.push({id:newId(),category,cents:amount,start:first,end:''});
  monthsBetween(first,today().slice(0,7)).forEach((m,i)=>{const add=(type,amount,name,category,day,goalId='')=>s.transactions.push({id:newId(),type,cents:amount,name,category,date:m+'-'+String(day).padStart(2,'0'),goalId,note:'Sample data',payment:type==='expense'?(['savor','disney','cash'][i%3]):'',incomeKind:'Bonus'});add('expense',4500+i*137,'A little shopping','Shopping',8);add('expense',2890+i*80,'Dinner out','Dining',12);add('expense',6400+i*210,'Concert night','Entertainment',17);add('expense',3200,'Skincare refill','Beauty',19);add('expense',2100+i*70,'Getting around','Transport',23);add('saving',22000,'NYC contribution','Savings',4,goal.id);add('saving',30000,'Disney contribution','Savings',4,disney.id);add('saving',50000,'Future me','Savings',4,s.goals[2].id);if(i===5)add('income',15000,'Unexpected little #win','Income',14);});return validateState(s);}
function handleAction(action,id=''){
  if(action==='new-card')return accountModal();
  if(action==='edit-account')return accountModal(id);if(action==='card-payment')return cardPaymentModal(id);if(action==='account-history'){paymentFilter=id;page='activity';scope='all';typeFilter='all';categoryFilter='all';search='';render();return;}
  if(action==='new-income-rule')return ruleModal('income');if(action==='new-bill')return ruleModal('expense');if(action==='edit-rule')return ruleModal('',id);if(action==='end-rule')return endRuleModal(id);
  if(action==='new-income')return entryModal('income');if(action==='new-expense')return entryModal('expense');if(action==='edit-entry')return id.startsWith('auto:')?overrideModal(id):entryModal('',id);
  if(action==='new-goal')return goalModal();if(action==='edit-goal')return goalModal(id);if(action==='contribute')return entryModal('saving','',id);if(action==='withdraw')return entryModal('withdrawal','',id);if(action==='goal-spend')return entryModal('expense','',id);if(action==='edit-budget')return budgetModal(id);
  if(action==='new-category')return formModal('Add a category',field('Category name','name','','text','maxlength="60" required'),f=>commit(next=>{const name=String(f.get('name')).trim();if(!name)throw Error('Enter a name.');if(next.categories.some(c=>c.toLowerCase()===name.toLowerCase()))throw Error('That category already exists.');next.categories.push(name);}),'Add category');
  if(action==='close-dialog')return closeDialog();
  if(action==='delete-entry'){if(!confirm('Delete this entry?'))return;commit(next=>next.transactions=next.transactions.filter(t=>t.id!==id));closeDialog();}
  if(action==='delete-goal'){if(db.transactions.some(t=>t.goalId===id))throw Error('This goal has history. Keep it, or remove its transactions before deleting it.');if(!confirm('Delete this goal and its opening balance?'))return;commit(next=>next.goals=next.goals.filter(g=>g.id!==id));closeDialog();}
  if(action==='skip-auto'){commit(next=>next.overrides[id]=null);closeDialog();notify('Skipped this month. Restore skipped entries in Settings.');}
  if(action==='reset-auto'){commit(next=>delete next.overrides[id]);closeDialog();}
  if(action==='previous-month'||action==='next-month'){const m=shiftMonth(month,action==='previous-month'?-1:1);if(m<'1900-01'||m>'2099-12')return;month=m;}
  if(action==='export'){download(`pink-ledger${demo?'-SAMPLE':''}-${today()}.json`,JSON.stringify(db,null,2),'application/json');notify('Backup downloaded ♡');return;}
  if(action==='recovery'){download('pink-ledger-recovery.json',recovery,'application/json');return;}
  if(action==='import'){$('#importFile').click();return;}
  if(action==='export-csv'){const q=v=>'"'+String(v??'').replace(/"/g,'""')+'"',rows=filteredActivity();const csv=[['Date','Type','Description','Category','Amount USD','Goal','Automatic','Payment method','Merchant','Note'],...rows.map(t=>[t.date,t.type,t.name,t.category,(t.cents/100).toFixed(2),db.goals.find(g=>g.id===t.goalId)?.name||'',t.automatic?'Yes':'No',paymentLabel(t.payment),t.merchant||'',t.note])].map(r=>r.map(v=>q(/^[=+@-]/.test(String(v))?"'"+v:v)).join(',')).join('\r\n');download('pink-ledger-activity.csv',csv,'text/csv;charset=utf-8');return;}
  if(action==='load-more'){activityLimit+=100;$('#activityBody').innerHTML=activityBody();return;}
  if(action==='enter-demo'){if(demo)return;realDb=db;db=sampleState();demo=true;page='dashboard';scope='month';month=today().slice(0,7);}
  if(action==='exit-demo'){if(!demo)return;db=realDb;realDb=null;demo=false;page='dashboard';}
  if(action==='restore-skipped'){commit(next=>delete next.overrides[id]);notify('Recurring entry restored.');}
  render();
}
// Skipped recurring entries stay recoverable without creating duplicate income or bills.
const originalSettingsView=settingsView;
settingsView=function(){const skipped=Object.entries(db.overrides).filter(([,v])=>v===null);return originalSettingsView()+(skipped.length?heading('Skipped recurring entries')+`<div class="card">${skipped.map(([id])=>{const [,ruleId,m]=id.split(':'),r=db.rules.find(r=>r.id===ruleId);return `<div class="list-row"><div class="list-detail"><div class="list-title">${esc(r?.name||'Recurring item')}</div><div class="list-meta">${esc(monthLabel(m))}</div></div>${button('restore-skipped','Restore',id,'small')}</div>`;}).join('')}</div>`:'');};
document.addEventListener('click',e=>{const target=e.target.closest('[data-page],[data-action],[data-scope]');if(!target)return;e.preventDefault();try{if(target.dataset.page){page=target.dataset.page;if(page==='activity'){scope='all';activityLimit=100;}render();window.scrollTo({top:0,behavior:'instant'});}else if(target.dataset.scope){scope=target.dataset.scope;activityLimit=100;render();}else handleAction(target.dataset.action,target.dataset.id||'');}catch(err){if($('#dialog').open)$('#formError').textContent=err.message;else notify(err.message);}});
document.addEventListener('change',async e=>{
  if(e.target.id==='monthInput'&&e.target.value){month=e.target.value;render();}
  if(e.target.id==='paymentFilter'){paymentFilter=e.target.value;activityLimit=100;$('#activityBody').innerHTML=activityBody();}
  if(e.target.id==='typeFilter'||e.target.id==='categoryFilter'){if(e.target.id==='typeFilter')typeFilter=e.target.value;else categoryFilter=e.target.value;activityLimit=100;$('#activityBody').innerHTML=activityBody();}
  if(e.target.id==='importFile'){const file=e.target.files?.[0];if(!file)return;try{if(file.size>10000000)throw Error('Choose a backup under 10 MB.');const candidate=validateState(JSON.parse(await file.text()));if(!confirm('Replace this ledger with the selected backup? Export first if you want to keep a copy.'))return;if(!demo){localStorage.setItem(KEY,JSON.stringify(candidate));storageBlocked=false;}db=candidate;render();notify('Backup restored ♡');}catch(err){notify('Could not restore: '+err.message);}finally{e.target.value='';}}
});
document.addEventListener('input',e=>{if(e.target.id==='searchActivity'){search=e.target.value;activityLimit=100;$('#activityBody').innerHTML=activityBody();}});
$('#closeDialog').onclick=closeDialog;$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const rect=$('#dialog').getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeDialog();}});
render();
